import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Button, TextField, Select, MenuItem, FormControl, InputLabel } from '@mui/material';

const ManageCandidates = () => {
    const [schools, setSchools] = useState([]);
    const [courses, setCourses] = useState([]);
    const [formData, setFormData] = useState({
        name: '',
        part: '',
        school: '',
        course: '',
        position: '',
        manifesto_topic: '',
        manifesto_body: '',
        photo_url: '',
        video_url: ''
    });

    useEffect(() => {
        axios.get('http://localhost/backend/getSchools.php')
            .then(response => setSchools(response.data))
            .catch(error => console.error('Error fetching schools:', error));
    }, []);

    useEffect(() => {
        if (formData.school) {
            axios.get(`http://localhost/backend/getCourses.php?school=${formData.school}`)
                .then(response => setCourses(response.data))
                .catch(error => console.error('Error fetching courses:', error));
        }
    }, [formData.school]);

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        axios.post('http://localhost/backend/addCandidate.php', formData)
            .then(response => alert(response.data.message))
            .catch(error => console.error('Error adding candidate:', error));
    };

    return (
        <form onSubmit={handleSubmit}>
            <TextField label="Name" name="name" onChange={handleChange} required fullWidth />
            <TextField label="Part" name="part" onChange={handleChange} required fullWidth />

            <FormControl fullWidth>
                <InputLabel>School</InputLabel>
                <Select name="school" value={formData.school} onChange={handleChange} required>
                    {schools.map(school => (
                        <MenuItem key={school.code} value={school.code}>{school.name}</MenuItem>
                    ))}
                </Select>
            </FormControl>

            <FormControl fullWidth>
                <InputLabel>Course</InputLabel>
                <Select name="course" value={formData.course} onChange={handleChange} required>
                    {courses.map(course => (
                        <MenuItem key={course.code} value={course.code}>{course.name}</MenuItem>
                    ))}
                </Select>
            </FormControl>

            <TextField label="Position" name="position" onChange={handleChange} required fullWidth />
            <TextField label="Manifesto Topic" name="manifesto_topic" onChange={handleChange} required fullWidth />
            <TextField label="Manifesto Body" name="manifesto_body" onChange={handleChange} multiline rows={4} required fullWidth />
            <TextField label="Photo URL" name="photo_url" onChange={handleChange} fullWidth />
            <TextField label="Video URL" name="video_url" onChange={handleChange} fullWidth />

            <Button type="submit" variant="contained" color="primary">Save</Button>
        </form>
    );
};

export default ManageCandidates;
